const w = p.width; const d = p.depth; const t = p.thickness; const cl = p.clearance; const hingeR = 8; const hingeW = 15; 

// Base plate
const base = drawRoundedRectangle(w, d, 5).sketchOnPlane('XY').extrude(t);
const lip = drawRectangle(w, 10).sketchOnPlane('XY', t).extrude(t * 2);
const baseFinal = base.fuse(lip);

// Hinge section on base
const hingeBase = makeCylinder(hingeR, hingeW, [-w / 2 + hingeW / 2, -d / 2 + hingeR, t], [1, 0, 0]);
const baseFinalWithHinge = baseFinal.fuse(hingeBase);

// Adjustable Backplate
const backPlate = drawRoundedRectangle(w, d - 20, 5).sketchOnPlane('XY').extrude(t);
const hingeArm = makeCylinder(hingeR - cl, hingeW - (cl * 2), [0, 0, 0], [1, 0, 0]).translate([-w/2 + hingeW/2, 0, 0]);
const backplateFinal = backPlate.fuse(hingeArm).rotate(45, [0, 0, 0], [1, 0, 0]).translateZ(t + hingeR);

return { base: baseFinalWithHinge, backplate: backplateFinal };
